import React from 'react';
import { Box, type Types } from '@fiverr-private/theme';
import { focusAbleProps } from '../../utils/focusable';
import { useIsDaySelected } from '../hooks';

interface CircleWrapperDayProps {
  isDisabled: boolean;
  currentDay: Date;
  isDayBetweenSelectedDates: boolean;
  isEndHoveredDay: boolean;
  children: React.ReactNode;
}
const CircleWrapperDay = ({
  currentDay,
  isDayBetweenSelectedDates,
  isEndHoveredDay,
  isDisabled,
  children,
}: CircleWrapperDayProps) => {
  const isDaySelected = useIsDaySelected(currentDay);

  const getBackgroundColor = (): Types.SelectorBackgroundColorsType => {
    if (isDaySelected) {
      return 'grey_1200';
    }
    if (isEndHoveredDay) {
      return 'grey_500';
    }
    if (isDayBetweenSelectedDates) {
      return { hover: 'grey_500' };
    }
    if (isDisabled) {
      return 'transparent';
    }
    return { hover: 'grey_200' };
  };

  return (
    <Box
      display="flex"
      ratio="1"
      {...focusAbleProps({ isDisabled, isSelected: isDaySelected })}
      alignItems="center"
      justifyContent="center"
      backgroundColor={getBackgroundColor()}
      borderRadius="circle"
      width="auto"
      height="100%"
      zIndex="1"
    >
      {children}
    </Box>
  );
};

CircleWrapperDay.displayName = 'CircleWrapperDay';
export default CircleWrapperDay;
