import React from 'react';
import { Container, Stack } from '@fiverr-private/layout_components';
import { Button } from '@fiverr-private/button';
import { onEnterClicked } from '../Views/utils/focusable';
import useViewHeader from './viewsUtil';
import HeaderButton from './HeaderButton';

const CalendarHeader = () => {
  const { formatTitle, changeViewMode } = useViewHeader();

  return (
    <Stack
      dataTrackTag={'calendar_header'}
      width="100%"
      gap="0"
      flex="0 0 auto"
      direction="row"
      justifyContent="spaceBetween"
      alignItems="center"
    >
      <HeaderButton buttonType="prev" />
      <Container>
        <Button
          onKeyDown={onEnterClicked(changeViewMode)}
          onClick={changeViewMode}
          intent="primary"
          size="sm"
          variant="ghost"
          dataTrackTag="change_view_button"
        >
          {formatTitle()}
        </Button>
      </Container>
      <HeaderButton buttonType="next" />
    </Stack>
  );
};

CalendarHeader.displayName = 'CalendarHeader';
export default CalendarHeader;
