import { translate } from '@fiverr-private/i18n-react';
import { useCalendarContext } from '../../CalendarContext';
import { createDateWithFix2DigitYear, FIRST_DATE_IN_MONTH, FIRST_MONTH_IN_YEAR } from '../../utils/date';
import { isYearDisabled } from '../../Views/utils/disabledDates';
import useIsDateAllowed from '../../hooks/useIsDateAllowed';
import type { ButtonType, ViewHeaderUtil } from './types';
import { formatYearsTitle } from './formatTitle';
import { isNavigateDisabled } from './isNavigateDisabled';

const useYearsViewHeaderUtil: ViewHeaderUtil = () => {
    const { startRangeDate, setViewMode, setStartRangeDate, allowedDatesRange } = useCalendarContext();
    const checkIsInAllowedRange = useIsDateAllowed();

    const prevLabel = translate('calendar.header.years.previous');
    const nextLabel = translate('calendar.header.years.next');

    const startYear = startRangeDate.getFullYear() - (startRangeDate.getFullYear() % 10) + 1;

    const getNextYears = (buttonType: ButtonType) => startYear + (buttonType === 'next' ? 1 : -1) * 10;

    const update = (buttonType: ButtonType) => {
        if (disableNavigate(buttonType)) {
            return false;
        }

        const newYear = getNextYears(buttonType);
        const updatedDate = createDateWithFix2DigitYear(newYear, FIRST_MONTH_IN_YEAR, FIRST_DATE_IN_MONTH);
        setStartRangeDate(updatedDate);
        return true;
    };

    const changeViewMode = () => setViewMode('days');

    const isPrevButtonDisabled = () =>
        isYearDisabled(startYear - 1, checkIsInAllowedRange) && isYearDisabled(startYear - 10, checkIsInAllowedRange);

    const isNextButtonDisabled = () =>
        isYearDisabled(startYear + 10, checkIsInAllowedRange) && isYearDisabled(startYear + 19, checkIsInAllowedRange);

    const disableNavigate = (buttonType: ButtonType) =>
        isNavigateDisabled({
            nextDisabled: isNextButtonDisabled(),
            prevDisabled: isPrevButtonDisabled(),
            buttonType,
            allowedDatesRange,
            startRangeDate,
        });

    return {
        formatTitle: () => formatYearsTitle(startRangeDate),
        update,
        changeViewMode,
        prevLabel,
        nextLabel,
        disableNavigate,
    };
};

export default useYearsViewHeaderUtil;
