import React from 'react';
import { Stack } from '@fiverr-private/layout_components';
import { Text } from '@fiverr-private/typography';
import type { Types } from '@fiverr-private/theme';
import { focusAbleProps, onEnterClicked } from '../utils/focusable';
import { daysInSelectedRangeBackground } from '../DaysView/utils';

interface MonthsAndYearItemProps {
  onClick: () => void;
  isDisabled: boolean;
  isSelected: boolean;
  date: string;
}
const MonthsAndYearItem = ({ isDisabled, isSelected, onClick, date }: MonthsAndYearItemProps) => {
  const getBackgroundColor = (): Types.SelectorBackgroundColorsType => {
    if (isDisabled) {
      return 'transparent';
    }
    if (isSelected) {
      return 'grey_1200';
    }

    return { hover: daysInSelectedRangeBackground };
  };

  const getTextColor = (): Types.BodyColors => {
    if (isSelected) {
      return 'white';
    }
    if (isDisabled) {
      return 'bodySecondary';
    }

    return 'bodyPrimary';
  };

  return (
    <Stack
      {...focusAbleProps({ isDisabled, isSelected })}
      onKeyDown={onEnterClicked(onClick)}
      cursor={isDisabled ? 'default' : 'pointer'}
      borderRadius="lg"
      backgroundColor={getBackgroundColor()}
      alignItems="center"
      justifyContent="center"
      width="100%"
      padding="3"
      onClick={isDisabled ? undefined : onClick}
    >
      <Text size="b_sm" color={getTextColor()} decoration={isDisabled ? 'lineThrough' : 'none'}>
        {date}
      </Text>
    </Stack>
  );
};

MonthsAndYearItem.displayName = 'MonthsAndYearItem';
export default MonthsAndYearItem;
