import type { KeyboardEvent } from 'react';
import classnames from 'classnames';
import type { Types } from '@fiverr-private/theme';
import * as styles from './styles.ve.css';

export const onEnterClicked =
    (callback: () => void) =>
    ({ key }: KeyboardEvent<HTMLElement>) => {
        if (key === 'Enter') {
            callback();
        }
    };

interface FocusAblePropsParams {
    isDisabled: boolean;
    isSelected: boolean;
}
export const focusAbleProps = ({ isDisabled, isSelected }: FocusAblePropsParams): Partial<Types.FlexLayoutProps> => ({
    tabIndex: isDisabled ? -1 : 0,
    outlineWidth: { focusVisible: 'md' },
    outlineStyle: { focusVisible: 'solid' },
    outlineColor: { focusVisible: 'grey_1200', default: 'transparent' },
    borderColor: 'transparent',
    borderStyle: 'solid',
    borderWidth: 'sm',
    className: classnames({ [styles.selectedFocusable]: isSelected }),
});
