import React from 'react';
import { ChevronButton } from '@fiverr-private/button';
import { onEnterClicked } from '../../Views/utils/focusable';
import useViewHeader from '../viewsUtil';
import type { ButtonType } from '../viewsUtil/types';

interface HeaderButtonProps {
  buttonType: ButtonType;
}
const HeaderButton = ({ buttonType }: HeaderButtonProps) => {
  const { update, prevLabel, nextLabel, disableNavigate } = useViewHeader();
  const isPrev = buttonType === 'prev';
  const direction = isPrev ? 'left' : 'right';
  return (
    <ChevronButton
      dataTrackTag="calander_header_button"
      dataTrackValue={direction}
      ariaLabel={isPrev ? prevLabel : nextLabel}
      disabled={disableNavigate(buttonType)}
      onKeyDown={onEnterClicked(() => update(buttonType))}
      onClick={() => update(buttonType)}
      size="sm"
      shape="circle"
      chevronDirection={direction}
    />
  );
};

HeaderButton.displayName = 'HeaderButton';
export default HeaderButton;
