import { type Dispatch, type SetStateAction, useEffect, useState } from 'react';
import type { CalendarModeProps, NullableDate } from '../types';
import { FIRST_DATE_IN_MONTH, getStartDay } from '../utils/date';

const getStartMonth = (startDate: NullableDate): Date => {
    const date = getStartDay(startDate || new Date());
    date.setDate(FIRST_DATE_IN_MONTH);

    return date;
};

// When selectedDate (startDate/endDate) change then we need to update the RangeDate that we show to the user
const useRefreshRangeDate = (selectedDate: NullableDate, setStartRangeDate: Dispatch<SetStateAction<Date>>) =>
    useEffect(() => {
        if (selectedDate) {
            setStartRangeDate(getStartMonth(selectedDate));
        }
    }, [selectedDate, setStartRangeDate]);

const useStartRangeDate = ({ calendarMode, date, initialDate }: Partial<CalendarModeProps>) => {
    let startDate;
    let endDate;
    if (calendarMode === 'single') {
        startDate = date || initialDate;
        endDate = null;
    } else if (calendarMode === 'range') {
        startDate = (date || initialDate)?.start;
        endDate = (date || initialDate)?.end;
    }
    const [startRangeDate, setStartRangeDate] = useState<Date>(() => getStartMonth(startDate));
    useRefreshRangeDate(startDate, setStartRangeDate);
    useRefreshRangeDate(endDate, setStartRangeDate);

    return { startRangeDate, setStartRangeDate };
};
export default useStartRangeDate;
