import React from 'react';
import { Stack } from '@fiverr-private/layout_components';
import DayContent from '../DayContent';
import FillingSelectedDayEdges from '../FillingSelectedDayEdges';
import type { NullableDate } from '../../../types';

interface DayItemProps {
  currentDay: Date;
  isDisabled: boolean;
  hovered: NullableDate;
}
const DayItem = ({ currentDay, hovered, isDisabled }: DayItemProps) => (
  <Stack
    cursor={isDisabled ? 'default' : 'pointer'}
    justifyContent="center"
    alignItems="center"
    width="100%"
    height="100%"
    gap="0"
    position="relative"
  >
    <FillingSelectedDayEdges currentDay={currentDay} hovered={hovered} />
    <DayContent isDisabled={isDisabled} hovered={hovered} currentDay={currentDay}></DayContent>
  </Stack>
);

DayItem.displayName = 'DayItem';
export default DayItem;
