import { DATETIME_ELEMENT_STYLES, dateTimeFormat } from '@fiverr-private/localization';
import { getContext } from '@fiverr-private/fiverr_context';

export const formatDaysTitle = (startRangeDate: Date): string => {
    const { locale } = getContext();

    return dateTimeFormat({
        value: startRangeDate,
        options: {
            month: DATETIME_ELEMENT_STYLES.LONG,
            year: DATETIME_ELEMENT_STYLES.NUMERIC,
            fallbackValue: startRangeDate.toLocaleString(locale, { month: 'long', year: 'numeric' }),
        },
    });
};

export const formatMonthsTitle = (startRangeDate: Date): string => startRangeDate.getFullYear().toString();

export const formatYearsTitle = (startRangeDate: Date): string => {
    const startYear = startRangeDate.getFullYear() - (startRangeDate.getFullYear() % 10) + 1;
    const endYear = startYear + 9;

    return `${startYear} - ${endYear}`;
};
