import React, { useEffect, useState } from 'react';
import { Grid, GridItem } from '@fiverr-private/layout_components';
import { Text } from '@fiverr-private/typography';
import { getStartDay } from '../../utils/date';
import useIsDateAllowed from '../../hooks/useIsDateAllowed';
import { useCalendarContext } from '../../CalendarContext';
import type { NullableDate } from '../../types';
import { onEnterClicked } from '../utils/focusable';
import DayItem from './DayItem';
import { useGetAdjacentDays, useGetShortWeekDaysNames } from './hooks';

const DaysView = () => {
  const { date, onDateChanged, calendarMode } = useCalendarContext();
  const [hovered, setHovered] = useState<NullableDate>(null);

  useEffect(() => {
    if (calendarMode === 'single' && hovered) {
      setHovered(null);
    }
  }, [calendarMode, hovered]);

  const allDays = useGetAdjacentDays();
  const shortWeekDaysNames = useGetShortWeekDaysNames();

  const isDateAllowed = useIsDateAllowed();

  const onDayClick = (selectedDate: Date) => {
    if (!isDateAllowed(selectedDate)) {
      return;
    }

    if (calendarMode === 'single') {
      onDateChanged(selectedDate as NullableDate);
    } else if (calendarMode === 'range') {
      if (!date.start || selectedDate < getStartDay(date.start) || (date.start && date.end)) {
        onDateChanged({ start: selectedDate, end: null });
      } else if (date.start && selectedDate >= getStartDay(date.start) && !date.end) {
        onDateChanged({ start: date.start, end: selectedDate });
      }
    }
    setHovered(null);
  };

  const updateHovered = (day: Date) => {
    const hoveredState = calendarMode === 'range' && isDateAllowed(day) ? day : null;
    setHovered(hoveredState);
  };

  return (
    <Grid
      height="100%"
      width="100%"
      onMouseOut={() => setHovered(null)}
      templateRows="7_cols"
      templateColumns="7_cols"
      flexGrow={1}
      gap="0"
      paddingX="3"
      style={{ justifyItems: 'center' }}
    >
      {shortWeekDaysNames.map((day) => (
        <GridItem key={day} onMouseOver={() => setHovered(null)}>
          <Text size="b_sm" fontWeight="semibold">
            {day}
          </Text>
        </GridItem>
      ))}
      {allDays.map((day) => (
        <GridItem
          onKeyDown={onEnterClicked(() => onDayClick(day))}
          key={day.toLocaleDateString()}
          alignItems="center"
          justifyContent="center"
          width="100%"
          height="100%"
          onClick={() => onDayClick(day)}
          onMouseOver={() => updateHovered(day)}
          onMouseOut={(e) => e.stopPropagation()}
        >
          <DayItem isDisabled={!isDateAllowed(day)} hovered={hovered} currentDay={day} />
        </GridItem>
      ))}
    </Grid>
  );
};

DaysView.displayName = 'DaysView';
export default DaysView;
