import type { AllowedDatesRange } from '../../types';
import type { ButtonType } from './types';

interface IsNavigateDisabled {
    buttonType: ButtonType;
    prevDisabled: boolean;
    nextDisabled: boolean;
    allowedDatesRange: AllowedDatesRange;
    startRangeDate: Date;
}
export const isNavigateDisabled = ({
    buttonType,
    prevDisabled,
    nextDisabled,
    allowedDatesRange,
    startRangeDate,
}: IsNavigateDisabled) => {
    let prev = prevDisabled;
    let next = nextDisabled;
    if (prevDisabled && nextDisabled) {
        const { min, max } = allowedDatesRange;
        if ((min as Date) > startRangeDate) {
            next = false;
        } else if ((max as Date) < startRangeDate) {
            prev = false;
        }
    }
    return buttonType === 'prev' ? prev : next;
};
