import { useMemo } from 'react';
import { getContext } from '@fiverr-private/fiverr_context';
import { FIRST_MONTH_IN_YEAR } from '../../../utils/date';

const useGetShortWeekDaysNames = () =>
    useMemo(() => {
        const dayInWeek = 7;
        const { locale } = getContext();
        const mapDayToName = {};
        const RANDOM_YEAR = 0;
        for (let day = 0; day < dayInWeek; day++) {
            const dayName = new Date(RANDOM_YEAR, FIRST_MONTH_IN_YEAR, day)
                .toLocaleDateString(locale, { weekday: 'short' })
                .substring(0, 2);
            mapDayToName[day] = dayName;
        }
        const startDay = 1;

        return Array.from(Array(dayInWeek), (_, i) => {
            const day = (i + startDay) % 7;

            return mapDayToName[day];
        });
    }, []);

export default useGetShortWeekDaysNames;
