import React from 'react';
import { Container } from '@fiverr-private/layout_components';
import { checkIsToDay } from '../utils';
import { useIsDaySelected } from '../hooks';

interface TodayIndicatorProps {
  currentDay: Date;
}
const TodayIndicator = ({ currentDay }: TodayIndicatorProps) => {
  const isDaySelected = useIsDaySelected(currentDay);
  if (!checkIsToDay(currentDay) || isDaySelected) {
    return null;
  }

  return (
    <Container
      position="absolute"
      bottom="0px"
      backgroundColor="grey_1200"
      borderRadius="circle"
      width="4px"
      height="4px"
    />
  );
};

TodayIndicator.displayName = 'TodayIndicator';
export default TodayIndicator;
