import React from 'react';
import { Container } from '@fiverr-private/layout_components';
import type { Types } from '@fiverr-private/theme';
import { getStartDay, isDateEqual } from '../../../utils/date';
import { useCalendarContext } from '../../../CalendarContext';
import { daysInSelectedRangeBackground } from '../utils';
import { useIsEndHoveredDay } from '../hooks';
import type { NullableDate } from '../../../types';

interface FillingSelectedDayEdgesProps {
  currentDay: Date;
  hovered: NullableDate;
}

// The selected date has a circle background and the date between the selected dates also has square background
// so the edges of a square of the area between the circle of the selected date to the square background looks bad
// without this component that fill the edges of a square with daysInSelectedRangeBackground
const FillingSelectedDayEdges = ({ currentDay, hovered }: FillingSelectedDayEdgesProps) => {
  const { date, calendarMode } = useCalendarContext();
  const isEndHoveredDay = useIsEndHoveredDay(currentDay, hovered);
  if (calendarMode === 'single') {
    return null;
  }

  const { start, end } = date;
  if (isDateEqual(start, end)) {
    return null;
  }

  let positions: Pick<Types.ContainerProps, 'right' | 'left'> | undefined;

  if (isDateEqual(end, currentDay) || isEndHoveredDay) {
    positions = { right: '50%', left: '0px' };
  }
  const isNextDayWithGreyBG = end || (start && hovered && getStartDay(start) < hovered);
  if (isDateEqual(start, currentDay) && isNextDayWithGreyBG) {
    positions = { right: '0px', left: '50%' };
  }

  if (!positions) {
    return null;
  }

  return (
    <Container
      {...positions}
      bottom="0px"
      top="0px"
      position="absolute"
      backgroundColor={daysInSelectedRangeBackground}
    />
  );
};

FillingSelectedDayEdges.displayName = 'FillingSelectedDayEdges';
export default FillingSelectedDayEdges;
