import { useEffect, useState } from 'react';
import type { CalendarModeProps } from '../types';

const useInnerDate = (initialDate: CalendarModeProps['initialDate']) => {
    const [innerDate, setInnerDate] = useState(initialDate);
    useEffect(() => {
        setInnerDate(initialDate);
    }, [initialDate]);

    const isInnerDateTypeCompatibleWithInitialDateType =
        innerDate === initialDate || initialDate instanceof Date === innerDate instanceof Date;

    return {
        innerDate: isInnerDateTypeCompatibleWithInitialDateType ? innerDate : initialDate,
        setInnerDate,
    };
};
export default useInnerDate;
