import { useCalendarContext } from '../../CalendarContext';
import type { ViewMode } from '../../types';
import useMonthsViewHeaderUtil from './monthsViewHeaderUtil';
import useDaysViewHeaderUtil from './daysViewHeaderUtil';
import useYearsViewHeaderUtil from './yearsViewHeaderUtil';
import type { ViewHeaderUtil } from './types';

const useViewHeader: ViewHeaderUtil = () => {
    const { viewMode } = useCalendarContext();

    const viewsUtils: { [key in ViewMode]: ReturnType<ViewHeaderUtil> } = {
        days: useDaysViewHeaderUtil(),
        months: useMonthsViewHeaderUtil(),
        years: useYearsViewHeaderUtil(),
    };

    return viewsUtils[viewMode];
};

export default useViewHeader;
