import { DATETIME_ELEMENT_STYLES, dateTimeFormat } from '@fiverr-private/localization';

const NUM_MONTHS_IN_YEAR = 12;
const RANDOM_YEAR = 2000;

export const getMonthsNames = (locale: string) =>
    Array.from(Array(NUM_MONTHS_IN_YEAR), (_, monthIndex) => {
        const date = new Date(RANDOM_YEAR, monthIndex, 1);
        return dateTimeFormat({
            value: date,
            options: {
                month: DATETIME_ELEMENT_STYLES.LONG,
                fallbackValue: date.toLocaleString(locale, { month: 'long' }),
            },
        });
    });
