import React from 'react';
import { useCalendarContext } from '../../CalendarContext';
import MonthsAndYearContainer from '../MonthsAndYearContainer';
import MonthsAndYearItem from '../MonthsAndYearItem';
import { createDateWithFix2DigitYear, FIRST_DATE_IN_MONTH, FIRST_MONTH_IN_YEAR } from '../../utils/date';
import useIsDateAllowed from '../../hooks/useIsDateAllowed';
import { isYearDisabled } from '../utils/disabledDates';

const YearsView = () => {
  const { startRangeDate, setStartRangeDate, setViewMode, date, calendarMode } = useCalendarContext();
  const checkIsInAllowedRange = useIsDateAllowed();

  const onYearClick = (year: number) => {
    const updatedDate = createDateWithFix2DigitYear(year, FIRST_MONTH_IN_YEAR, FIRST_DATE_IN_MONTH);
    setStartRangeDate(updatedDate);
    setViewMode('months');
  };

  const isYearSelected = (year: number): boolean => {
    if (calendarMode === 'single') {
      return date?.getFullYear() === year;
    }
    return date.start?.getFullYear() === year || date.end?.getFullYear() === year;
  };

  const startYear = startRangeDate.getFullYear() - (startRangeDate.getFullYear() % 10) + 1;

  const NUM_YEARS_TO_SHOW_IN_VIEW = 10;
  return (
    <MonthsAndYearContainer>
      {Array.from(Array(NUM_YEARS_TO_SHOW_IN_VIEW), (_, year) => year + startYear).map((year) => (
        <MonthsAndYearItem
          key={year}
          isDisabled={isYearDisabled(startRangeDate.getFullYear(), checkIsInAllowedRange)}
          date={year.toString()}
          onClick={() => onYearClick(year)}
          isSelected={isYearSelected(year)}
        />
      ))}
    </MonthsAndYearContainer>
  );
};

YearsView.displayName = 'YearsView';
export default YearsView;
