import { useCallback } from 'react';
import { useCalendarContext } from '../CalendarContext';
import { getStartDay } from '../utils/date';

const useIsDateAllowed = (): ((date: Date) => boolean) => {
    const {
        allowedDatesRange: { min, max },
    } = useCalendarContext();

    return useCallback(
        (date: Date) => {
            const startDay = getStartDay(date);
            const isAfterMinDate = !min || startDay >= getStartDay(min);
            const isBeforeMaxDate = !max || startDay <= getStartDay(max);

            return isAfterMinDate && isBeforeMaxDate;
        },
        [min, max]
    );
};

export default useIsDateAllowed;
