import { useCalendarContext } from '../../../CalendarContext';
import { isDateEqual } from '../../../utils/date';

const useIsDaySelected = (currentDay: Date): boolean => {
    const { date, calendarMode } = useCalendarContext();

    if (calendarMode === 'single') {
        return isDateEqual(date, currentDay);
    }
    return isDateEqual(date?.start, currentDay) || isDateEqual(date?.end, currentDay);
};
export default useIsDaySelected;
