import type { NullableDate } from '../types';

export const getStartDay = (date: Date) => {
    const startDay = new Date(date.toDateString());
    fix2DigitYear(date.getFullYear(), startDay);

    return startDay;
};

export const createDateWithFix2DigitYear = (year: number, month: number, date: number) => {
    const updateDate = new Date(year, month, date);
    fix2DigitYear(year, updateDate);

    return updateDate;
};

const fix2DigitYear = (fullYear: number, date: Date): void => {
    if (fullYear < 100 && date.getFullYear() !== fullYear) {
        date.setFullYear(fullYear);
    }
};

export const isDateEqual = (date1: NullableDate, date2: NullableDate) =>
    !!date1 && !!date2 && date1.toDateString() === date2.toDateString();

export const FIRST_DATE_IN_MONTH = 1;
export const FIRST_MONTH_IN_YEAR = 0;

// In the Date object days start from 1 and set day to 0 means to the last day in the prev month
export const LAST_DATE_IN_PREV_MONTH = 0;

// In the Date object months start from 0 and set month to 12 means to the first month in the next year
export const FIRST_MONTH_IN_NEXT_YEAR = 12;
