import { translate } from '@fiverr-private/i18n-react';
import { useCalendarContext } from '../../CalendarContext';
import { createDateWithFix2DigitYear, FIRST_DATE_IN_MONTH, FIRST_MONTH_IN_YEAR } from '../../utils/date';
import { isYearDisabled } from '../../Views/utils/disabledDates';
import useIsDateAllowed from '../../hooks/useIsDateAllowed';
import { formatMonthsTitle } from './formatTitle';
import type { ButtonType, ViewHeaderUtil } from './types';
import { isNavigateDisabled } from './isNavigateDisabled';

const useMonthsViewHeaderUtil: ViewHeaderUtil = () => {
    const { startRangeDate, setViewMode, setStartRangeDate, allowedDatesRange } = useCalendarContext();
    const checkIsInAllowedRange = useIsDateAllowed();

    const prevLabel = translate('calendar.header.months.previous');
    const nextLabel = translate('calendar.header.months.next');

    const update = (buttonType: ButtonType) => {
        if (disableNavigate(buttonType)) {
            return false;
        }
        const newYear = startRangeDate.getFullYear() + (buttonType === 'next' ? 1 : -1);
        const updatedDate = createDateWithFix2DigitYear(newYear, FIRST_MONTH_IN_YEAR, FIRST_DATE_IN_MONTH);
        setStartRangeDate(updatedDate);
        return true;
    };

    const changeViewMode = () => setViewMode('years');
    const isPrevButtonDisabled = () => isYearDisabled(startRangeDate.getFullYear() - 1, checkIsInAllowedRange);
    const isNextButtonDisabled = () => isYearDisabled(startRangeDate.getFullYear() + 1, checkIsInAllowedRange);

    const disableNavigate = (buttonType: ButtonType) =>
        isNavigateDisabled({
            nextDisabled: isNextButtonDisabled(),
            prevDisabled: isPrevButtonDisabled(),
            buttonType,
            allowedDatesRange,
            startRangeDate,
        });

    return {
        formatTitle: () => formatMonthsTitle(startRangeDate),
        update,
        changeViewMode,
        prevLabel,
        nextLabel,
        disableNavigate,
    };
};

export default useMonthsViewHeaderUtil;
