import React from 'react';
import { getContext } from '@fiverr-private/fiverr_context';
import { useCalendarContext } from '../../CalendarContext';
import MonthsAndYearContainer from '../MonthsAndYearContainer';
import MonthsAndYearItem from '../MonthsAndYearItem';
import useIsDateAllowed from '../../hooks/useIsDateAllowed';
import { isMonthDisabled } from '../utils/disabledDates';
import { getMonthsNames } from './getMonthsNames';

const MonthsView = () => {
  const { startRangeDate, setStartRangeDate, setViewMode, date, calendarMode } = useCalendarContext();
  const { locale } = getContext();
  const monthsNames = getMonthsNames(locale);
  const isMonthSelected = (monthIndex: number): boolean => {
    if (calendarMode === 'single') {
      return startRangeDate.getFullYear() === date?.getFullYear() && date?.getMonth() === monthIndex;
    }
    const { start, end } = date;
    const isStart = startRangeDate.getFullYear() === start?.getFullYear() && start?.getMonth() === monthIndex;
    const isEnd = startRangeDate.getFullYear() === end?.getFullYear() && end?.getMonth() === monthIndex;

    return isStart || isEnd;
  };

  const checkIsInAllowedRange = useIsDateAllowed();

  const onMonthClick = (monthIndex: number) => {
    const updatedDate = new Date(startRangeDate);
    updatedDate.setMonth(monthIndex);
    setStartRangeDate(updatedDate);
    setViewMode('days');
  };

  return (
    <MonthsAndYearContainer>
      {monthsNames.map((month, monthIndex) => (
        <MonthsAndYearItem
          key={month}
          isDisabled={isMonthDisabled(startRangeDate.getFullYear(), monthIndex, checkIsInAllowedRange)}
          date={month}
          onClick={() => onMonthClick(monthIndex)}
          isSelected={isMonthSelected(monthIndex)}
        />
      ))}
    </MonthsAndYearContainer>
  );
};

MonthsView.displayName = 'MonthsView';
export default MonthsView;
