import { userEvent, within } from '@storybook/test';
import { takeScreenshot } from '@fiverr-private/e2e_storybook_utils';
import { formatDaysTitle, formatMonthsTitle } from '../CalendarHeader/viewsUtil/formatTitle';
import { getMonthsNames } from '../Views/MonthsView/getMonthsNames';

export const DELAY = 50;

export const clickAndTakeScreenshot = async (element: HTMLElement) => {
    await userEvent.click(element, { delay: DELAY });
    await takeScreenshot();
};

const selectRange = async (start: HTMLElement, end: HTMLElement) => {
    await userEvent.click(start);
    await userEvent.click(end);
    await takeScreenshot();
};
export const getElementByDate = (date: Date, canvas: ReturnType<typeof within>) =>
    canvas.getByLabelText(date.toLocaleDateString());

export const selectRangeByDate = async (startDate: Date, endDate: Date, canvas: ReturnType<typeof within>) => {
    const start = getElementByDate(startDate, canvas);
    const end = getElementByDate(endDate, canvas);
    await selectRange(start, end);
};

export const selectRangeByText = async (canvas: ReturnType<typeof within>) => {
    let start: HTMLElement | null = null;
    let end: HTMLElement | null = null;
    try {
        start = canvas.getByText(10);
        end = canvas.getByText(20);
    } catch (e) {
        return;
    }
    if (start && end) {
        await selectRange(start, end);
    }
};

export const selectRangeInMonthView = async (canvas: ReturnType<typeof within>, locale: string) => {
    const monthsNames = getMonthsNames(locale);
    const monthEl = canvas.getByText(monthsNames[7]);
    await clickAndTakeScreenshot(monthEl);
    await selectRangeByText(canvas);
};

export const openMonthsView = async (canvas: ReturnType<typeof within>) => {
    const currentDate = new Date(canvas.getByText(10).ariaLabel as string);
    const headerButton = canvas.getByText(formatDaysTitle(currentDate));
    await clickAndTakeScreenshot(headerButton);
};

export const openYearsView = async (canvas: ReturnType<typeof within>): Promise<Date> => {
    const currentDate = new Date(canvas.getByText(10).ariaLabel as string);
    let headerButton = canvas.getByText(formatDaysTitle(currentDate));
    await userEvent.click(headerButton);

    headerButton = canvas.getByText(formatMonthsTitle(currentDate));
    await clickAndTakeScreenshot(headerButton);

    return currentDate;
};

export const selectRangeInYearsView = async (year: number, canvas: ReturnType<typeof within>) => {
    const yearEl = canvas.getByText(year);
    await clickAndTakeScreenshot(yearEl);
    await selectRangeInMonthView(canvas, 'en-US');
};
