import { translate } from '@fiverr-private/i18n-react';
import { useCalendarContext } from '../../CalendarContext';
import { isMonthDisabled } from '../../Views/utils/disabledDates';
import useIsDateAllowed from '../../hooks/useIsDateAllowed';
import { formatDaysTitle } from './formatTitle';
import type { ButtonType, ViewHeaderUtil } from './types';
import { isNavigateDisabled } from './isNavigateDisabled';

const useDaysViewHeaderUtil: ViewHeaderUtil = () => {
    const { startRangeDate, setViewMode, setStartRangeDate, allowedDatesRange } = useCalendarContext();
    const checkIsInAllowedRange = useIsDateAllowed();

    const prevLabel = translate('calendar.header.days.previous');
    const nextLabel = translate('calendar.header.days.next');

    const update = (buttonType: ButtonType) => {
        if (disableNavigate(buttonType)) {
            return false;
        }

        const updatedDate = new Date(startRangeDate);
        updatedDate.setMonth(startRangeDate.getMonth() + (buttonType === 'next' ? 1 : -1));
        setStartRangeDate(updatedDate);

        return true;
    };

    const changeViewMode = () => setViewMode('months');
    const isPrevButtonDisabled = () =>
        isMonthDisabled(startRangeDate.getFullYear(), startRangeDate.getMonth() - 1, checkIsInAllowedRange);
    const isNextButtonDisabled = () =>
        isMonthDisabled(startRangeDate.getFullYear(), startRangeDate.getMonth() + 1, checkIsInAllowedRange);

    const disableNavigate = (buttonType: ButtonType) =>
        isNavigateDisabled({
            nextDisabled: isNextButtonDisabled(),
            prevDisabled: isPrevButtonDisabled(),
            buttonType,
            allowedDatesRange,
            startRangeDate,
        });

    return {
        formatTitle: () => formatDaysTitle(startRangeDate),
        update,
        changeViewMode,
        prevLabel,
        nextLabel,
        disableNavigate,
    };
};

export default useDaysViewHeaderUtil;
