import React, { createContext, ReactNode, useState } from 'react';
import type {
  ViewMode,
  AllowedDatesRange,
  NullableDate,
  ControlledCalendarProps,
  CalendarModeProps,
  RangeDate,
  CalendarProps,
} from '../types';
import useStartRangeDate from './useStartRangeDate';
import useInnerDate from './useInnerDate';

type CalendarContextType = ControlledCalendarProps & {
  viewMode: ViewMode;
  setViewMode: (viewMode: ViewMode) => void;
  allowedDatesRange: AllowedDatesRange;
  startRangeDate: Date;
  setStartRangeDate: (startRangeDate: Date) => void;
};

const CalendarContext = createContext<CalendarContextType>({} as CalendarContextType);

export const useCalendarContext = () => {
  const context = React.useContext(CalendarContext);

  if (!context) {
    throw new Error('useCalendarContext must be used within a CalendarProvider');
  }

  return context;
};

export const CalendarProvider = ({
  calendarMode,
  onDateChanged,
  date,
  initialDate,
  allowedDatesRange,
  children,
}: Pick<CalendarProps, 'calendarMode' | 'onDateChanged' | 'date' | 'initialDate' | 'allowedDatesRange'> & {
  children: ReactNode;
}) => {
  const [viewMode, setViewMode] = useState<ViewMode>('days');
  const { innerDate, setInnerDate } = useInnerDate(initialDate);
  const { startRangeDate, setStartRangeDate } = useStartRangeDate({
    date,
    initialDate: innerDate,
    calendarMode,
  } as Partial<CalendarModeProps>);

  return (
    <CalendarContext.Provider
      value={
        {
          calendarMode,
          viewMode,
          setViewMode,
          onDateChanged: (date: NullableDate | RangeDate) => {
            setInnerDate(date);
            onDateChanged?.(date as NullableDate & RangeDate);
          },
          date: date || innerDate,
          startRangeDate,
          setStartRangeDate,
          allowedDatesRange,
        } as CalendarContextType
      }
    >
      {children}
    </CalendarContext.Provider>
  );
};
